import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 单元 2 复习与自测 · 第33–40课","description":"L21–L40 原创练习和答案解析。","frontmatter":{"title":"第三册：培养技能 · 单元 2 复习与自测 · 第33–40课","description":"L21–L40 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-3/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 2 复习与自测","summary":"L21–L40 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 2 复习与自测 · 第21–32课","link":"/life/english/new-concept/book-3/unit-02/review-part-01"},"next":{"text":"第三册：培养技能 · 单元 3：第41—60课：比较、论证与审慎表达","link":"/life/english/new-concept/book-3/unit-03/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 2 复习与自测 · 第21–32课","link":"/life/english/new-concept/book-3/unit-02/review-part-01"},"next":{"text":"第三册：培养技能 · 单元 3：第41—60课：比较、论证与审慎表达","link":"/life/english/new-concept/book-3/unit-03/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/review-part-02.md","filePath":"life/english/new-concept/book-3/unit-02/review-part-02.md"}'),n={name:"life/english/new-concept/book-3/unit-02/review-part-02.md"};function r(i,e,l,h,p,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第三册-培养技能-·-单元-2-复习与自测-·-第33–40课" tabindex="-1">第三册：培养技能 · 单元 2 复习与自测 · 第33–40课 <a class="header-anchor" href="#第三册-培养技能-·-单元-2-复习与自测-·-第33–40课" aria-label="Permalink to &quot;第三册：培养技能 · 单元 2 复习与自测 · 第33–40课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-33-·-否定副词前置倒装" tabindex="-1">Lesson 33 · 否定副词前置倒装 <a class="header-anchor" href="#lesson-33-·-否定副词前置倒装" aria-label="Permalink to &quot;Lesson 33 · 否定副词前置倒装 {#lesson-33-·-否定副词前置倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Never had I seen the station so quiet before that morning.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>改写：I rarely travel without a notebook.（Rarely 开头）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Rarely do I travel without a notebook.</p><p><strong>解析：</strong> 补入 do 并把主语置于其后。</p></details><p><strong>表达迁移：</strong> 写三句难忘经历，包含一个倒装句和具体细节。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rarely have I travelled through such dense fog. The bus stopped beside a closed bakery for nearly an hour. When sunlight finally reached the windows, everyone cheered.</p><p>倒装给整体感受，后两句提供可见情节支持感受。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">回看本课</a></p><h2 id="lesson-34-·-分词状语的逻辑主语" tabindex="-1">Lesson 34 · 分词状语的逻辑主语 <a class="header-anchor" href="#lesson-34-·-分词状语的逻辑主语" aria-label="Permalink to &quot;Lesson 34 · 分词状语的逻辑主语 {#lesson-34-·-分词状语的逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Looking beneath the frame, Maya noticed a small handwritten label.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>例句是谁查看画框下方？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Maya</p><p><strong>解析：</strong> 分词逻辑主语应与主句主语一致。</p></details><p><strong>表达迁移：</strong> 用三句描述发现旧物，包含一个主语一致的分词短语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Sorting the books, I found a sketch between two pages. A date in the corner caught my eye. I photographed the sketch before asking the owner about its history.</p><p>分词主语清楚，发现后先记录再询问，未把猜测写成价值鉴定。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">回看本课</a></p><h2 id="lesson-35-·-情态动词的被动结构" tabindex="-1">Lesson 35 · 情态动词的被动结构 <a class="header-anchor" href="#lesson-35-·-情态动词的被动结构" aria-label="Permalink to &quot;Lesson 35 · 情态动词的被动结构 {#lesson-35-·-情态动词的被动结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Both statements should be examined before a decision is announced.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>例句能证明双方陈述已经审查吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> should 表示应当采取的措施。</p></details><p><strong>表达迁移：</strong> 写三句虚构社区争议处理流程，包含一项原则和两项具体步骤。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Every complaint should be heard without interruption. The chair recorded each resident&#39;s main concern. A written explanation was sent after the meeting.</p><p>第一句说明原则，后二句报告实际动作，建议与事实清楚分开。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">回看本课</a></p><h2 id="lesson-36-·-so-与-such-的结果结构" tabindex="-1">Lesson 36 · so 与 such 的结果结构 <a class="header-anchor" href="#lesson-36-·-so-与-such-的结果结构" aria-label="Permalink to &quot;Lesson 36 · so 与 such 的结果结构 {#lesson-36-·-so-与-such-的结果结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It was such an unexpected meeting that neither of us spoke for a moment.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>填空：There were ___ many similarities that we laughed.（so/such）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> so</p><p><strong>解析：</strong> many 的数量结构用 so many。</p></details><p><strong>表达迁移：</strong> 写三句巧合经历，不编造具体概率。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I found my former classmate in a tiny bookshop abroad. We had both come to buy the same dictionary. It was such a surprising coincidence that we forgot to ask the price.</p><p>细节说明惊讶原因，未将罕见感受包装成数学概率。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">回看本课</a></p><h2 id="lesson-37-·-by、until-与时刻表现在时" tabindex="-1">Lesson 37 · by、until 与时刻表现在时 <a class="header-anchor" href="#lesson-37-·-by、until-与时刻表现在时" aria-label="Permalink to &quot;Lesson 37 · by、until 与时刻表现在时 {#lesson-37-·-by、until-与时刻表现在时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We must reach the platform by six, although the train does not leave until ten past.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>例句最迟几点到站台？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 六点。</p><p><strong>解析：</strong> by six 表示截止时间。</p></details><p><strong>表达迁移：</strong> 写三句赶车计划，区分列车时间、个人截止点和等候时间。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The train leaves at 7:20. We should reach the station by seven. If the platform is closed, we will wait in the hall until it opens.</p><p>三个时间表达分别控制离站、到达和等候，行为安排清楚。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">回看本课</a></p><h2 id="lesson-38-·-目的不定式与-for-doing" tabindex="-1">Lesson 38 · 目的不定式与 for doing <a class="header-anchor" href="#lesson-38-·-目的不定式与-for-doing" aria-label="Permalink to &quot;Lesson 38 · 目的不定式与 for doing {#lesson-38-·-目的不定式与-for-doing}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The group marked a stone each evening to keep track of passing days.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>例句的目的部分从哪个词开始？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> to keep track of ... 说明标记的目的。</p></details><p><strong>表达迁移：</strong> 设计一种虚构的简单记录法，用三句说明材料、操作和限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We place one bead in a jar to mark each day. A red bead marks the start of a new week. The system fails if someone forgets to add a bead.</p><p>目的清楚，规则可操作，并指出依赖持续执行这一限制。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">回看本课</a></p><h2 id="lesson-39-·-不定式后置修饰与介词" tabindex="-1">Lesson 39 · 不定式后置修饰与介词 <a class="header-anchor" href="#lesson-39-·-不定式后置修饰与介词" aria-label="Permalink to &quot;Lesson 39 · 不定式后置修饰与介词 {#lesson-39-·-不定式后置修饰与介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had a reliable guide to consult and a marked path to follow.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>补全：There is nothing to worry ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> about</p><p><strong>解析：</strong> worry about 的介词保留。</p></details><p><strong>表达迁移：</strong> 用三句向旅伴说明一次徒步准备，既给依据也保留注意事项。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We have a clear map to follow. The ranger has checked the lower trail this morning. We should still watch for loose stones after the rain.</p><p>安慰建立在地图与检查上，最后一句避免把已有准备等同于零风险。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">回看本课</a></p><h2 id="lesson-40-·-反身代词与相互代词" tabindex="-1">Lesson 40 · 反身代词与相互代词 <a class="header-anchor" href="#lesson-40-·-反身代词与相互代词" aria-label="Permalink to &quot;Lesson 40 · 反身代词与相互代词 {#lesson-40-·-反身代词与相互代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The two actors introduced themselves before they introduced each other to the director.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>例句的 themselves 指谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两位演员各自本人。</p><p><strong>解析：</strong> 反身代词回指主语成员。</p></details><p><strong>表达迁移：</strong> 写三句说明一次角色排练，明确谁介绍谁以及谁独自准备。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Nina introduced herself as the host. She then introduced Omar to the audience. Omar had prepared the entire demonstration by himself.</p><p>人名和代词交替使用但指向清楚，by himself 补充独立准备的信息。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">回看本课</a></p>',68)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
